const mdFiles = files.filter(f => f.name && f.name.endsWith('.md') && f.type === 'file');
if (mdFiles.length === 0) throw new Error('설계 문서(.md) 파일이 없습니다.');

return mdFiles.map(f => ({ json: { name: f.name, url: f.url } }));

