  repo: meta.repo || '',
  repo_type: 'mobile',
  call_flow: parsed.call_flow || [],
  design_gaps: parsed.design_gaps || [],
  commit_count: meta.commit_count || 0,
  active_days: meta.active_days || 0,
  screen_flow: parsed.screen_flow || [],
  api_calls: parsed.api_calls || [],
  commit_messages: meta.commit_messages || [],
  error: null
} }];

const items = $input.all();
if (items.length === 1) return [items[0]];
return [{ json: {
  agent_id: 'WBS-MOB',
  results: items.map(i => i.json),
  error: null
} }];

const grc = $('GRC Build Output').first().json;
const dda = $('DDA Parse & Build Output').first().json;
const bak = $('BAK Aggregate Results').first().json;
const frt = $('FRT Aggregate Results').first().json;
const cfg = $('CFG Aggregate Results').first().json;
const mob = $('MOB Aggregate Results').first().json;

const agents = [
  { id: 'WBS-GRC', r: grc },
  { id: 'WBS-DDA', r: dda },
  { id: 'WBS-BAK', r: bak },
  { id: 'WBS-FRT', r: frt },
  { id: 'WBS-CFG', r: cfg },
  { id: 'WBS-MOB', r: mob }
];

const summary = agents.map(a => {
  const r = a.r || {};
  const ok = !r.error;
  const det = {};
  if (a.id === 'WBS-GRC') {
    det.classified = (r._classified_detail || []).map(i => ({ repo: i.repo, type: i.type, reason: i.reason }));
  } else if (a.id === 'WBS-DDA') {
    det.endpoint_count = (r.endpoints || []).length;
    det.table_count = (r.tables || []).length;
    det.sequence_count = (r.sequences || []).length;
  } else if (a.id === 'WBS-BAK') {
    const eps = r.endpoints || r.extracted_endpoints || [];
    det.endpoint_count = eps.length;
    det.call_flow_count = (r.call_flow || []).length;
  } else if (a.id === 'WBS-FRT') {
    det.api_call_count = (r.api_calls || []).length;
    det.screen_flow_count = (r.screen_flow || []).length;
  } else if (a.id === 'WBS-CFG') {
    const gaps = r.design_gaps || [];
    det.component_count = (r.components || []).length;
    det.design_gap_count = gaps.length;
    det.high_severity = gaps.filter(g => (g.severity||'').toLowerCase() === 'high').length;
  } else if (a.id === 'WBS-MOB') {
    det.screen_flow_count = (r.screen_flow || []).length;
    det.api_call_count = (r.api_calls || []).length;
    det.design_gap_count = (r.design_gaps || []).length;
  }
  return {
    agent_id: a.id,
    status: ok ? 'PASS' : 'FAIL',
    repo: r.repo || '',
    repo_type: r.repo_type || '',
    commit_count: r.commit_count || 0,
    active_days: r.active_days || 0,
    error: r.error || null,
    details: det
  };
});

const passed = summary.filter(s => s.status === 'PASS').length;
return [{ json: {
  test_id: 'WBS-INT-PHASE1',
  tested_at: new Date().toISOString(),
  total: agents.length,
  passed,
  failed: agents.length - passed,
  result: passed === agents.length ? 'ALL_PASS' : 'PARTIAL_FAIL',
  agents: summary,
  raw: { grc, dda, bak, frt, cfg, mob }
} }];
